function viewManagerTeamsReadOnly() {

const teams =
typeof getTeams === "function"
      ? getTeams()
      : [];

const employees =
typeof getEmployees === "function"
      ? getEmployees()
      : [];

const modal =
afManagerCreateModal(
      "Teams & Team Leaders",
      "View teams, Team Leaders, members and assigned shifts."
    );

const content =
modal.querySelector(
      ".afManagerContent"
    );

  if (
    !Array.isArray(teams) ||
teams.length === 0
  ) {

content.innerHTML = `
<div style="
        padding:18px;
        background:#f5f5f5;
        border-radius:9px;
        color:#666;
      ">
        No teams have been created yet.
</div>
    `;

    return;
  }


  function employeeName(
employeeId
  ) {

const employee =
employees.find(
        item =>
          String(
item.employeeId
          ) ===
          String(employeeId)
      );

    return employee
      ? employee.fullName
      : employeeId;
  }


content.innerHTML =
teams.map(team => {

const memberIds =
Array.isArray(
team.memberEmployeeIds
        )
          ? team.memberEmployeeIds
          : [];

const memberNames =
memberIds.length
          ? memberIds
              .map(employeeName)
              .filter(Boolean)
          : (
Array.isArray(
team.members
              )
                ? team.members
                : []
            );

const leaderName =
team.leader ||
employeeName(
team.leaderEmployeeId
        ) ||
        "Not assigned";

      return `
<div style="
          border:1px solid #dfe5e1;
          border-radius:11px;
          padding:16px;
          margin-bottom:12px;
          background:#fff;
        ">

<div style="
display:flex;
justify-content:space-between;
            gap:15px;
align-items:flex-start;
          ">

<div style="flex:1;">

<strong style="
                color:#0b5d3b;
                font-size:18px;
              ">
                ${afManagerEscape(
team.name ||
                  "Unnamed Team"
                )}
</strong>

<div style="
                margin-top:10px;
                line-height:1.8;
                font-size:14px;
              ">

<div>
<strong>
                    Team Leader:
</strong>
                  ${afManagerEscape(
leaderName
                  )}
</div>

<div>
<strong>
                    Assigned Shift:
</strong>
                  ${afManagerEscape(
team.shiftName ||
                    "Not assigned"
                  )}
</div>

<div>
<strong>
                    Members:
</strong>
                  ${
memberNames.length
                      ? memberNames
                          .map(
                            name =>
afManagerEscape(
                                name
                              )
                          )
                          .join(", ")
                      : "No members assigned"
                  }
</div>

<div>
<strong>
                    Number of Members:
</strong>
                  ${memberNames.length}
</div>

</div>
</div>

<span style="
              padding:6px 10px;
              border-radius:20px;
              background:#eef8f2;
              color:#0b5d3b;
              font-size:12px;
font-weight:bold;
            ">
              ${afManagerEscape(
                String(
team.status ||
                  "active"
                ).toUpperCase()
              )}
</span>

</div>

</div>
      `;

    }).join("");
}


