/* =========================================================
   ADVANCES & DEDUCTIONS
   ========================================================= */

function manageEmployeeAdvancesAndDeductions() {
const employees = getEmployees();

const modal =
document.createElement("div");

modal.style.cssText = `
position:fixed;
    inset:0;
background:rgba(0,0,0,.65);
    z-index:9999;
display:flex;
align-items:center;
justify-content:center;
    padding:20px;
  `;

modal.innerHTML = `
<div style="
background:white;
width:min(1100px,100%);
      max-height:94vh;
overflow:auto;
      border-radius:14px;
      padding:22px;
    ">
<h2 style="margin-top:0;">
        Employee Advances & Deductions
</h2>

<div style="
display:grid;
        grid-template-columns:
          repeat(auto-fit,minmax(180px,1fr));
        gap:10px;
      ">
<div>
<label>Employee</label>
<select id="payrollEmployee"
            style="width:100%;padding:9px;">
            ${employees.map(employee => `
<option value="${employee.employeeId}">
                ${employee.fullName}
                (${employee.employeeId})
</option>
            `).join("")}
</select>
</div>

<div>
<label>Type</label>
<select id="adjustmentType"
            style="width:100%;padding:9px;">
<option value="advance">
              Advance
</option>
<option value="deduction">
              Deduction
</option>
</select>
</div>

<div>
<label>Date</label>
<input id="adjustmentDate"
            type="date"
            value="${new Date()
              .toISOString()
              .slice(0,10)}"
            style="width:100%;padding:9px;">
</div>

<div>
<label>Amount (UGX)</label>
<input id="adjustmentAmount"
            type="number"
            min="0"
            style="width:100%;padding:9px;">
</div>

<div>
<label>Payroll Year</label>
<input id="adjustmentYear"
            type="number"
            value="${new Date().getFullYear()}"
            style="width:100%;padding:9px;">
</div>

<div>
<label>Payroll Month</label>
<select id="adjustmentMonth"
            style="width:100%;padding:9px;">
            ${Array.from(
              {length:12},
              (_,i) => `
<option value="${i}">
                  ${new Date(
                    2020,i,1
                  ).toLocaleString(
                    "en-US",
                    {month:"long"}
                  )}
</option>
              `
            ).join("")}
</select>
</div>

<div>
<label>Reason</label>
<input id="adjustmentReason"
            type="text"
            style="width:100%;padding:9px;">
</div>

<div>
<label>Approved By</label>
<input id="adjustmentApprovedBy"
            type="text"
            style="width:100%;padding:9px;">
</div>

<div style="grid-column:1/-1;">
<label>Remarks</label>
<textarea id="adjustmentRemarks"
            style="width:100%;padding:9px;"></textarea>
</div>
</div>

<button id="saveAdjustment"
        style="
          margin-top:14px;
          background:#198754;
color:white;
          border:0;
          padding:11px 18px;
          border-radius:7px;
font-weight:bold;
        ">
        Save Transaction
</button>

<h3 style="margin-top:25px;">
        Current Advances
</h3>

<div style="overflow:auto;">
<table style="
          width:100%;
border-collapse:collapse;
        ">
<thead>
<tr>
<th style="padding:8px;text-align:left;">Employee</th>
<th style="padding:8px;">Date</th>
<th style="padding:8px;">Amount</th>
<th style="padding:8px;">Recovered This Month</th>
<th style="padding:8px;">Outstanding</th>
<th style="padding:8px;">Reason</th>
</tr>
</thead>
<tbody id="advanceTableBody"></tbody>
</table>
</div>

<h3 style="margin-top:25px;">
        Deductions
</h3>

<div style="overflow:auto;">
<table style="
          width:100%;
border-collapse:collapse;
        ">
<thead>
<tr>
<th style="padding:8px;">Employee</th>
<th style="padding:8px;">Month</th>
<th style="padding:8px;">Amount</th>
<th style="padding:8px;">Reason</th>
<th style="padding:8px;">Approved By</th>
</tr>
</thead>
<tbody id="deductionTableBody"></tbody>
</table>
</div>

<div style="text-align:right;margin-top:20px;">
<button id="closeAdjustments"
          style="
            padding:10px 18px;
            border:0;
            border-radius:7px;
          ">
          Close
</button>
</div>
</div>
  `;

document.body.appendChild(modal);

  function refreshTables() {
const employeeMap = {};

employees.forEach(employee => {
employeeMap[employee.employeeId] =
employee.fullName;
    });

const advances =
getEmployeeAdvances();

const recoveries =
getAdvanceRecoveries();

const year =
      Number(
modal.querySelector(
          "#adjustmentYear"
        ).value
      );

const month =
      Number(
modal.querySelector(
          "#adjustmentMonth"
        ).value
      );

modal.querySelector(
      "#advanceTableBody"
    ).innerHTML =
advances.map(advance => {
const recoveredThisMonth =
          recoveries
            .filter(
              item =>
item.advanceId ===
advance.id&&
                Number(item.year) === year &&
                Number(item.month) === month
            )
            .reduce(
              (total,item) =>
                total +
                Number(item.amount || 0),
              0
            );

const outstanding =
getEmployeeAdvanceOutstanding(
advance.id
          );

        return `
<tr style="border-top:1px solid #ddd;">
<td style="padding:8px;">
              ${employeeMap[
advance.employeeId
              ] || advance.employeeName}
</td>
<td style="padding:8px;">
              ${advance.date || ""}
</td>
<td style="padding:8px;">
              ${formatPayrollMoney(
advance.amount
              )}
</td>
<td style="padding:8px;">
              ${formatPayrollMoney(
recoveredThisMonth
              )}
</td>
<td style="
              padding:8px;
font-weight:bold;
            ">
              ${formatPayrollMoney(
                outstanding
              )}
</td>
<td style="padding:8px;">
              ${advance.reason || ""}
</td>
</tr>
        `;
      }).join("");

const deductions =
getEmployeeDeductions()
        .filter(
          item =>
            Number(item.year) === year &&
            Number(item.month) === month
        );

modal.querySelector(
      "#deductionTableBody"
    ).innerHTML =
deductions.map(item => `
<tr style="border-top:1px solid #ddd;">
<td style="padding:8px;">
            ${employeeMap[
item.employeeId
            ] || item.employeeName}
</td>
<td style="padding:8px;">
            ${payrollMonthName(
              year,
              month
            )}
</td>
<td style="padding:8px;">
            ${formatPayrollMoney(
item.amount
            )}
</td>
<td style="padding:8px;">
            ${item.reason || ""}
</td>
<td style="padding:8px;">
            ${item.approvedBy || ""}
</td>
</tr>
      `).join("");
  }

modal.querySelector(
    "#adjustmentMonth"
  ).value =
    new Date().getMonth();

modal.querySelector(
    "#saveAdjustment"
  ).onclick = () => {
const employeeId =
modal.querySelector(
        "#payrollEmployee"
      ).value;

const employee =
employees.find(
        item =>
item.employeeId ===
employeeId
      );

const type =
modal.querySelector(
        "#adjustmentType"
      ).value;

const amount =
      Number(
modal.querySelector(
          "#adjustmentAmount"
        ).value
      );

    if (!amount || amount <= 0) {
      alert(
        "Please enter a valid amount."
      );
      return;
    }

const date =
modal.querySelector(
        "#adjustmentDate"
      ).value;

const year =
      Number(
modal.querySelector(
          "#adjustmentYear"
        ).value
      );

const month =
      Number(
modal.querySelector(
          "#adjustmentMonth"
        ).value
      );

const reason =
modal.querySelector(
        "#adjustmentReason"
      ).value.trim();

const approvedBy =
modal.querySelector(
        "#adjustmentApprovedBy"
      ).value.trim();

const remarks =
modal.querySelector(
        "#adjustmentRemarks"
      ).value.trim();

    if (type === "advance") {
const advances =
getEmployeeAdvances();

const advance = {
        id: Date.now(),
employeeId,
employeeName:
          employee?.fullName || "",
        date,
        amount,
        reason,
approvedBy,
        remarks,
createdAt:
          new Date().toISOString()
      };

advances.push(advance);
saveEmployeeAdvances(advances);

const initialRecovery =
        prompt(
          "Enter advance recovery for this month, or enter 0:",
          "0"
        );

const recoveryAmount =
        Number(initialRecovery || 0);

      if (
recoveryAmount> 0
      ) {
const recoveries =
getAdvanceRecoveries();

recoveries.push({
          id: Date.now() + 1,
advanceId:
advance.id,
employeeId,
employeeName:
            employee?.fullName || "",
          year,
          month,
          amount:
Math.min(
recoveryAmount,
              amount
            ),
          date,
approvedBy,
          remarks,
createdAt:
            new Date().toISOString()
        });

saveAdvanceRecoveries(
          recoveries
        );
      }
    } else {
const deductions =
getEmployeeDeductions();

deductions.push({
        id: Date.now(),
employeeId,
employeeName:
          employee?.fullName || "",
        date,
        year,
        month,
        amount,
        reason,
approvedBy,
        remarks,
        status: "APPROVED",
createdAt:
          new Date().toISOString()
      });

saveEmployeeDeductions(
        deductions
      );
    }

    alert(
      type === "advance"
        ? "Employee advance saved successfully."
        : "Employee deduction saved successfully."
    );

refreshTables();
  };

modal.querySelector(
    "#adjustmentYear"
  ).onchange = refreshTables;

modal.querySelector(
    "#adjustmentMonth"
  ).onchange = refreshTables;

modal.querySelector(
    "#closeAdjustments"
  ).onclick = () =>modal.remove();

refreshTables();
}


