/* =========================================================
   RECORD PAYROLL PAYMENT
   ========================================================= */

function recordPayrollPayment(
payrollId
) {
const records =
getPayrollRecords();

const index =
records.findIndex(
      item =>
        String(item.id) ===
        String(payrollId)
    );

  if (index < 0) {
    alert(
      "Payroll record not found."
    );
    return;
  }

const record =
    records[index];

const payment =
    Number(
      prompt(
        "Enter amount paid in UGX:",
        String(
record.balance || 0
        )
      )
    );

  if (!payment || payment <= 0) {
    return;
  }

  if (
    payment >
    Number(record.balance || 0)
  ) {
    alert(
      "Payment cannot exceed the outstanding balance for this payroll month."
    );
    return;
  }

record.amountPaid =
    Number(record.amountPaid || 0) +
    payment;

record.balance =
Math.max(
      Number(record.netPayable || 0) -
record.amountPaid,
      0
    );

record.paymentDate =
    new Date().toISOString();

record.status =
record.balance<= 0
      ? "PAID"
      : "PARTIALLY PAID";

record.updatedAt =
    new Date().toISOString();

  records[index] = record;

savePayrollRecords(records);

  alert(
    "Payroll payment recorded successfully."
  );

managePayrollLedger();
}


