  /* =======================================================
     SELECT CHECKLIST BY ROLE
     ======================================================= */

  function getAFRoleChecklist(
    role,
    automatic
  ) {

    if (role === "Manager") {

      return getAFManagerChecklist(
        automatic
      );

    }


    if (role === "Secretary") {

      return getAFSecretaryChecklist(
        automatic
      );

    }


    if (role === "Director") {

      return getAFDirectorChecklist(
        automatic
      );

    }


    return [];

  }


  /* =======================================================
     GET SAVED STATUS
     ======================================================= */

  function getAFChecklistItemStatus(
    item,
todayData
  ) {

    /*
     * Existing real system record has priority.
     */
    if (
item.automatic&&
item.done
    ) {

      return {

        completed: true,

        status: "DONE",

        source: "SYSTEM"

      };

    }


const saved =
todayData[item.id];


    if (
      saved &&
      (
saved.status === "DONE" ||
saved.status === "NO_ACTIVITY"
      )
    ) {

      return {

        completed: true,

        status:
saved.status,

        source: "MANUAL",

checkedBy:
saved.checkedBy || "",

checkedAt:
saved.checkedAt || ""

      };

    }


    return {

      completed: false,

      status: "PENDING",

      source: ""

    };

  }


  /* =======================================================
     SAVE MANUAL CHECK
     ======================================================= */

  function saveAFManualChecklistItem(
itemId,
    status
  ) {

const user =
getAFChecklistUser();


    if (!user) {
      return;
    }


const today =
getAFChecklistToday();


const data =
getAFChecklistStorage();


    if (!data[today]) {

      data[today] = {};

    }


    data[today][itemId] = {

      status: status,

checkedBy:
user.fullName ||
user.employeeId ||
        "",

checkedByEmployeeId:
user.employeeId ||
        "",

checkedByRole:
user.role ||
        "",

checkedAt:
        new Date().toISOString()

    };


saveAFChecklistStorage(
      data
    );

  }


