  function afReadArray(key) {

    try {

const value =
JSON.parse(
localStorage.getItem(key) || "[]"
      );

      return Array.isArray(value)
        ? value
        : [];

    } catch (error) {

console.error(
        "Storage read error:",
        key,
        error
      );

      return [];
    }
  }


  function afEscape(value) {

    return String(
      value ?? ""
    )
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#039;");
  }


  function afLocalDate() {

const now =
    new Date();

const year =
now.getFullYear();

const month =
    String(
now.getMonth() + 1
    ).padStart(2, "0");

const day =
    String(
now.getDate()
    ).padStart(2, "0");

    return (
      year +
      "-" +
      month +
      "-" +
      day
    );
  }


  /* =======================================================
     CALCULATE FACTORY STOCK
     ======================================================= */

  function getAFFactoryStock() {

const materialRecords =
afReadArray(
      "materialRecords"
    );

const productionRecords =
afReadArray(
      "productionRecords"
    );

const deliveryRecords =
afReadArray(
      "afDeliveryRecords"
    );


    /* -------------------------
       UNWASHED COMPANY KAVERA
       ------------------------- */

const unwashedKaveraKg =
materialRecords
  .filter(record => {

    return (
record.batchNumber&&
      String(
record.materialSource || ""
      ).toLowerCase() !== "client" &&
      String(
record.status || ""
      ).toUpperCase() !== "CANCELLED"
    );

  })
  .reduce(
    (total, record) => {

const balance =
typeof getBatchPendingKg ===
        "function"
          ? getBatchPendingKg(
record.batchNumber
            )
          : Number(
record.batchBalanceKg || 0
            );

      return total + balance;

    },
    0
  );


    /* -------------------------
       WASHED COMPANY KAVERA
       ------------------------- */

const washedKaveraKg =
    Number(
localStorage.getItem(
        "companyWashedKaveraStock"
      ) || 0
    );


const produced = {};

const delivered = {};


AF_POLE_TYPES.forEach(type => {

      produced[type.key] = 0;

      delivered[type.key] = 0;

    });


    /* -------------------------
       PRODUCTION
       ------------------------- */

productionRecords
      .filter(record => {

const status =
        String(
record.productionStatus ||
record.status ||
          ""
        ).toUpperCase();

        return (
          status !== "CANCELLED"
        );

      })
      .forEach(record => {

        /*
         * New production records
         */
        if (
Array.isArray(
record.poleEntries
          ) &&
record.poleEntries.length
        ) {

record.poleEntries
            .forEach(entry => {

const key =
              String(
entry.key || ""
              );

              if (
Object.prototype
                  .hasOwnProperty.call(
                    produced,
                    key
                  )
              ) {

                produced[key] +=
                Number(
entry.quantity || 0
                );

              }

            });

          return;
        }


        /*
         * Older production records
         */
        AF_POLE_TYPES
          .forEach(type => {

            produced[type.key] +=
            Number(
              record[type.key] || 0
            );

          });

      });


    /* -------------------------
       DELIVERIES
       ------------------------- */

deliveryRecords
      .filter(record => {

        return (
          String(
record.status || ""
          ).toUpperCase() !==
          "CANCELLED"
        );

      })
      .forEach(record => {

const items =
Array.isArray(record.items)
          ? record.items
          : [];

items.forEach(item => {

const key =
          String(
item.key || ""
          );

          if (
Object.prototype
              .hasOwnProperty.call(
                delivered,
                key
              )
          ) {

            delivered[key] +=
            Number(
item.quantity || 0
            );

          }

        });

      });


const balances = {};


AF_POLE_TYPES.forEach(type => {

      balances[type.key] =
Math.max(
        Number(
          produced[type.key] || 0
        ) -
        Number(
          delivered[type.key] || 0
        ),
        0
      );

    });


const totalProduced =
AF_POLE_TYPES.reduce(
      (total, type) =>
        total +
        Number(
          produced[type.key] || 0
        ),
      0
    );


const totalDelivered =
AF_POLE_TYPES.reduce(
      (total, type) =>
        total +
        Number(
          delivered[type.key] || 0
        ),
      0
    );


const totalBalance =
AF_POLE_TYPES.reduce(
      (total, type) =>
        total +
        Number(
          balances[type.key] || 0
        ),
      0
    );


    return {

unwashedKaveraKg,

washedKaveraKg,

      produced,

      delivered,

      balances,

totalProduced,

totalDelivered,

totalBalance,

deliveryRecords

    };
  }


