/* =========================================================
   DELIVERY HISTORY
   ========================================================= */

function afDeliveryType(record) {

const saved =
  String(
record.deliveryType || ""
  ).toLowerCase();

  if (saved) {
    return saved;
  }

  return Number(
record.pelletKg || 0
  ) > 0
    ? "pellets"
    : "poles";

}


function afDeliveryDetails(record) {

const type =
afDeliveryType(record);


  if (
    type === "pellets"
  ) {

const owner =
    String(
record.pelletOwnership || ""
    ).toLowerCase() === "client"
      ? "Client-Owned"
      : "A&F / Company";


    return (
      (record.pelletType || "Pellets") +
      " — " +
      Number(
record.pelletKg || 0
      ).toLocaleString() +
      " kg — " +
      owner
    );

  }


const items =
Array.isArray(
record.items
  )
    ? record.items
    : [];


  if (items.length) {

    return items
      .map(
        item =>
          (
item.name ||
item.key ||
            "Poles"
          ) +
          " × " +
          Number(
item.quantity || 0
          ).toLocaleString()
      )
      .join(", ");

  }


  return (
    Number(
record.totalPoles || 0
    ).toLocaleString() +
    " poles"
  );

}


