/* =========================================================
   DIRECTOR CANCEL / REVERSE
   ========================================================= */

modal.querySelectorAll(
  "[data-expense-cancel]"
).forEach(
  button => {

button.onclick =
function() {

  if (!isDirector) {

    alert(
      "Only the Director can cancel or reverse an expense."
    );

    return;

  }


const id =
this.getAttribute(
  "data-expense-cancel"
);


const latestRecords =
getAFExpenseRecords();


const record =
latestRecords.find(
  item =>
    String(
item.id
    ) ===
    String(id)
);


  if (!record) {

    alert(
      "Expense record could not be found."
    );

    return;

  }


const confirmed =
confirm(
  "Cancel and reverse this expense?\n\n" +
  "Expense No: " +
  (
record.expenseNumber ||
    "-"
  ) +
  "\nAmount: UGX " +
  Number(
record.amount || 0
  ).toLocaleString()
);


  if (!confirmed) {
    return;
  }


const reason =
prompt(
  "Please enter the reason for cancelling / reversing this expense:"
);


  if (
    !reason ||
    !reason.trim()
  ) {

    alert(
      "A cancellation reason is required."
    );

    return;

  }


record.status =
"CANCELLED";

record.cancellationReason =
reason.trim();

record.cancelledAt =
new Date()
  .toISOString();

record.cancelledByEmployeeId =
currentUser.employeeId ||
"";

record.cancelledByName =
currentUser.fullName ||
currentUser.employeeName ||
"";

record.cancelledByRole =
currentUser.role ||
"";


saveAFExpenseRecords(
latestRecords
);


alert(
  "Expense cancelled successfully.\n\n" +
  "It will no longer be included in expense totals."
);


openAFExpenses();

};

  }
);

