  function syncCustomerOpenOrders(
    customer
  ) {

const records =
orderList();


    let changed =
      false;


records.forEach(
      order => {

        if (
          String(
order.customerId || ""
          ) !==
          String(
customer.id || ""
          )
        ) {

          return;

        }


const status =
          String(
order.status || ""
          ).toUpperCase();


        if (
          [
            "QUOTED",
            "PENDING",
            "CONFIRMED",
            "PROCESSING"
          ].includes(
            status
          )
        ) {

order.customerName =
customer.name || "";


order.customerPhone =
customer.phone || "";


order.customerLocation =
customer.location || "";


order.customerEmail =
customer.email || "";


order.customerContactPerson =
customer.contactPerson || "";


order.customerType =
customer.customerType || "";


order.customerUpdatedAt =
            new Date()
              .toISOString();


          changed =
            true;

        }

      }
    );


    if (changed) {

      save(
K.orders,
        records
      );

    }

  }


