const stock = () => {
    try {
      return typeof window.getAFFactoryStock === "function"
        ? window.getAFFactoryStock()
        : { balances: {} };
    } catch (e) {
      return { balances: {} };
    }
  };

const itemText = r => {
const items =
Array.isArray(r.items)
        ? r.items
        : [];

    return items.length
      ? items
          .map(
i =>
              (i.name || i.key) +
              " × " +
              Number(
i.quantity || 0
              ).toLocaleString()
          )
          .join(", ")
      : (r.description || "-");
  };

