  function confirmRecord(id) {

const records =
orderList();


const r =
records.find(
        x =>
          String(x.id) ===
          String(id)
      );


    if (!r) {

      return alert(
        "Order / quotation not found."
      );

    }


r.type =
      "Order";

r.status =
      "CONFIRMED";

r.confirmedAt =
      new Date()
        .toISOString();

r.confirmedBy =
currentUser()
        .fullName ||
currentUser()
        .employeeId ||
      "";


    save(
K.orders,
      records
    );


    render();

  }


  function deliverRecord(id) {

const r =
orderList()
        .find(
          x =>
            String(x.id) ===
            String(id)
        );


    if (!r) {

      return alert(
        "Order not found."
      );

    }


    if (
      String(
r.status || ""
      ).toUpperCase() !==
      "CONFIRMED"
    ) {

      return alert(
        "Confirm the order first before converting it to a delivery."
      );

    }


    if (
typeof window.recordAFDelivery !==
      "function"
    ) {

      return alert(
        "Record Delivery could not be found."
      );

    }


wrap.remove();

const salesCustomersMain =
document.getElementById(
    "afSalesCustomersMain"
  );

if (salesCustomersMain) {
salesCustomersMain.remove();
}

window.recordAFDelivery();


    let tries = 0;


const fill = () => {

      tries++;


const m =
document.getElementById(
          "afRecordDeliveryModal"
        );


      if (!m) {

        if (tries < 10) {

setTimeout(
            fill,
            120
          );

        }

        return;

      }


const customer =
customerList()
          .find(
            c =>
              String(c.id) ===
              String(
r.customerId
              )
          );


const sel =
m.querySelector(
          "#afRegisteredCustomerSelect"
        );


      if (
sel&&
r.customerId
      ) {

sel.value =
r.customerId;


sel.dispatchEvent(
          new Event(
            "change",
            {
bubbles:true
            }
          )
        );

      }


const set =
        (id, value) => {

const el =
m.querySelector(id);

          if (el) {

el.value =
              value || "";

          }

        };


      set(
        "#afDeliveryCustomer",
r.customerName ||
customer?.name
      );


      set(
        "#afDeliveryPhone",
r.customerPhone ||
customer?.phone
      );


      set(
        "#afDeliveryPlace",
r.customerLocation ||
customer?.location
      );


      set(
        "#afDeliveryReference",
r.reference
      );


      (
Array.isArray(
r.items
        )
          ? r.items
          : []
      )
        .forEach(
i => {

const q =
m.querySelector(
                "#afDeliveryQty_" +
i.key
              );


            if (q) {

q.value =
                Number(
i.quantity || 0
                );


q.dispatchEvent(
                new Event(
                  "input",
                  {
bubbles:true
                  }
                )
              );

            }

          }
        );

    };


setTimeout(
      fill,
      120
    );

  }


