/* =========================================================
   OPEN GLOBAL PRINT DOCUMENT
   ========================================================= */

window.afOpenPrintDocument =
function(options = {}) {

const popup =
window.open(
            "",
            "_blank",
            "width=900,height=750"
        );


    if (!popup) {

        alert(
            "Please allow pop-ups so the document can open."
        );

        return null;
    }


popup.document.open();

popup.document.write(
window.afBuildPrintDocument(options)
    );

popup.document.close();

popup.focus();

    return popup;
};


