/* =========================================================
   HELPER FUNCTIONS
   ========================================================= */

function afMoney(value) {

    return "UGX " +
        (Number(value) || 0)
        .toLocaleString();
}


function afNumber(value) {

    return (Number(value) || 0)
        .toLocaleString(
            undefined,
            {maximumFractionDigits:2}
        );
}


function afEscape(value) {

    return String(value ?? "")
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#039;");
}

