/* =========================================================
   TRANSACTION ENTRY
   Director + Secretary
   ========================================================= */

function openTVSLATransactionEntry() {

    if (!tvslaAllowed()) {

        alert("Access Denied");
        return;
    }


const members =
tvslaMembers();


const memberOptions =
        members
            .filter(
                member =>
member.active !== false
            )
            .map(
                member => `

<option
                        value="${tvslaEscape(member.id)}"
>
                        ${tvslaEscape(member.name)}
</option>

                `
            )
            .join("");


const modal =
tvslaModal(
            "TVSLA Transaction Entry",
            `

<div style="
                background:#eef7f1;
                border:1px solid #cfe3d6;
                padding:11px;
                border-radius:9px;
                margin-bottom:14px;
                font-size:12px;
            ">

                Logged in as:
<b>
                    ${tvslaEscape(
tvslaCurrentUserName()
                    )}
</b>

&nbsp;|&nbsp;

                Role:
<b>
                    ${tvslaEscape(
tvslaRole()
                    )}
</b>

</div>


<form id="tvslaTransactionForm">

<div style="
display:grid;
                    grid-template-columns:
                        repeat(
                            auto-fit,
minmax(210px,1fr)
                        );
                    gap:12px;
                ">

<label>
                        Date
<input
                            id="tvslaTransactionDate"
                            type="date"
                            value="${tvslaToday()}"
                            required
                            style="${tvslaInputStyle()}"
>
</label>


<label>
                        Member

<select
                            id="tvslaTransactionMember"
                            required
                            style="${tvslaInputStyle()}"
>

<option value="">
                                Select Member
</option>

                            ${memberOptions}

</select>

</label>


<label>
                        Transaction Type

<select
                            id="tvslaTransactionType"
                            required
                            style="${tvslaInputStyle()}"
>

<option value="">
                                Select Transaction
</option>

<option value="Savings">
                                Savings / Contribution
</option>

<option value="Withdrawal">
                                Withdrawal
</option>

<option value="Loan Repayment">
                                Loan Repayment
</option>

<option value="Dividend / Interest">
                                Dividend / Interest
</option>

<option value="Other Income">
                                Other Income
</option>

</select>

</label>


<label>
                        Amount (UGX)

<input
                            id="tvslaTransactionAmount"
                            type="number"
                            min="1"
                            step="1"
                            required
                            style="${tvslaInputStyle()}"
>

</label>


<label>
                        Payment Method

<select
                            id="tvslaPaymentMethod"
                            style="${tvslaInputStyle()}"
>

<option value="Cash">
                                Cash
</option>

<option value="Mobile Money">
                                Mobile Money
</option>

<option value="Bank">
                                Bank
</option>

<option value="Other">
                                Other
</option>

</select>

</label>


<label>
                        Receipt / Reference

<input
                            id="tvslaReference"
                            type="text"
                            placeholder="Optional"
                            style="${tvslaInputStyle()}"
>

</label>

</div>


<label style="
display:block;
                    margin-top:12px;
                ">

                    Notes

<textarea
                        id="tvslaTransactionNotes"
                        rows="3"
                        style="${tvslaInputStyle()}"
></textarea>

</label>


<div style="
                    margin-top:15px;
display:flex;
                    gap:8px;
flex-wrap:wrap;
                ">

                    ${tvslaButton(
                        "Save Transaction",
                        "tvslaSaveTransactionBtn"
                    )}

                    ${
tvslaDirector()
                        ? tvslaButton(
                            "Back to Dashboard",
                            "tvslaBackDashboardBtn",
                            true
                        )
                        : ""
                    }

</div>

</form>

            `
        );


const form =
modal.querySelector(
            "#tvslaTransactionForm"
        );


form.onsubmit =
        function(event) {

event.preventDefault();


const memberId =
modal.querySelector(
                    "#tvslaTransactionMember"
                ).value;


const member =
tvslaMembers()
                    .find(
                        item =>
item.id ===
memberId
                    );


            if (!member) {

                alert(
                    "Please select a TVSLA member."
                );

                return;
            }


const amount =
                Number(
modal.querySelector(
                        "#tvslaTransactionAmount"
                    ).value
                );


            if (
                !Number.isFinite(amount) ||
                amount <= 0
            ) {

                alert(
                    "Enter a valid transaction amount."
                );

                return;
            }


const transactions =
tvslaTransactions();


transactions.push({

                id:
tvslaID("TXN"),

                date:
modal.querySelector(
                        "#tvslaTransactionDate"
                    ).value,

memberId:
member.id,

memberName:
member.name,

                type:
modal.querySelector(
                        "#tvslaTransactionType"
                    ).value,

                amount,

paymentMethod:
modal.querySelector(
                        "#tvslaPaymentMethod"
                    ).value,

                reference:
modal.querySelector(
                        "#tvslaReference"
                    ).value.trim(),

                notes:
modal.querySelector(
                        "#tvslaTransactionNotes"
                    ).value.trim(),

enteredBy:
tvslaCurrentUserName(),

enteredByRole:
tvslaRole(),

createdAt:
Date.now()

            });


tvslaWrite(
TVSLA_KEYS.transactions,
                transactions
            );


            alert(
                "TVSLA transaction saved successfully.\n\n" +
                "This transaction has NOT affected " +
                "the factory accounts."
            );


            /*
             * Secretary stays in transaction entry.
             * Director returns to TVSLA dashboard.
             */

            if (tvslaDirector()) {

openTVSLADashboard();

            } else {

openTVSLATransactionEntry();

            }

        };


const back =
modal.querySelector(
            "#tvslaBackDashboardBtn"
        );


    if (back) {

back.onclick =
openTVSLADashboard;
    }
}


/* =========================================================
   INPUT STYLE
   ========================================================= */

function tvslaInputStyle() {

    return `
display:block;
        width:100%;
box-sizing:border-box;
        margin-top:5px;
        padding:10px;
        border:1px solid #cbd8cf;
        border-radius:8px;
background:white;
        font-size:13px;
    `;
}


/* =========================================================
   MEMBERS - DIRECTOR ONLY
   ========================================================= */

function openTVSLAMembers() {

    if (!tvslaDirector()) {

        alert(
            "Director access required."
        );

        return;
    }


const members =
tvslaMembers();


const rows =
members.length
        ? members.map(
            member => `

<tr>

<td>
                        ${tvslaEscape(member.memberNo)}
</td>

<td>
                        ${tvslaEscape(member.name)}
</td>

<td>
                        ${tvslaEscape(member.phone)}
</td>

<td>
                        ${tvslaEscape(member.joinDate)}
</td>

<td>
                        ${
member.active === false
                            ? "Inactive"
                            : "Active"
                        }
</td>

</tr>

            `
        ).join("")
        : `

<tr>
<td
colspan="5"
                    style="
text-align:center;
                        padding:15px;
                    "
>
                    No members registered yet.
</td>
</tr>

        `;


const modal =
tvslaModal(
            "TVSLA Members",
            `

<form id="tvslaMemberForm">

<div style="
display:grid;
                    grid-template-columns:
                        repeat(
                            auto-fit,
minmax(190px,1fr)
                        );
                    gap:10px;
                ">

<input
                        id="tvslaMemberNo"
                        placeholder="Member Number"
                        required
                        style="${tvslaInputStyle()}"
>

<input
                        id="tvslaMemberName"
                        placeholder="Member Full Name"
                        required
                        style="${tvslaInputStyle()}"
>

<input
                        id="tvslaMemberPhone"
                        placeholder="Phone Number"
                        style="${tvslaInputStyle()}"
>

<input
                        id="tvslaMemberJoinDate"
                        type="date"
                        value="${tvslaToday()}"
                        required
                        style="${tvslaInputStyle()}"
>

</div>


<div style="
                    margin-top:12px;
                ">

                    ${tvslaButton(
                        "Register Member",
                        "tvslaSaveMemberBtn"
                    )}

                    ${tvslaButton(
                        "Back to Dashboard",
                        "tvslaMemberBackBtn",
                        true
                    )}

</div>

</form>


<div style="
                margin-top:18px;
overflow:auto;
            ">

<table style="
                    width:100%;
border-collapse:collapse;
                    font-size:12px;
                ">

<thead>

<tr style="
                            background:#eef7f1;
                        ">

<th>Member No.</th>
<th>Name</th>
<th>Phone</th>
<th>Joined</th>
<th>Status</th>

</tr>

</thead>

<tbody>
                        ${rows}
</tbody>

</table>

</div>

            `
        );


modal.querySelector(
        "#tvslaMemberForm"
    ).onsubmit =
        function(event) {

event.preventDefault();


const memberNo =
modal.querySelector(
                    "#tvslaMemberNo"
                ).value.trim();


const name =
modal.querySelector(
                    "#tvslaMemberName"
                ).value.trim();


            if (!memberNo || !name) {

                alert(
                    "Member number and name are required."
                );

                return;
            }


const list =
tvslaMembers();


            if (
list.some(
                    member =>
                        String(
member.memberNo
                        ).toLowerCase() ===
memberNo.toLowerCase()
                )
            ) {

                alert(
                    "That member number already exists."
                );

                return;
            }


list.push({

                id:
tvslaID("MEM"),

memberNo,

                name,

                phone:
modal.querySelector(
                        "#tvslaMemberPhone"
                    ).value.trim(),

joinDate:
modal.querySelector(
                        "#tvslaMemberJoinDate"
                    ).value,

                active: true,

createdAt:
Date.now()

            });


tvslaWrite(
TVSLA_KEYS.members,
                list
            );


            alert(
                "TVSLA member registered."
            );


openTVSLAMembers();

        };


modal.querySelector(
        "#tvslaMemberBackBtn"
    ).onclick =
openTVSLADashboard;
}


/* =========================================================
   LOANS - DIRECTOR ONLY
   ========================================================= */

function openTVSLALoans() {

    if (!tvslaDirector()) {

        alert(
            "Director access required."
        );

        return;
    }


const members =
tvslaMembers();


const memberOptions =
members.map(
            member => `

<option
                    value="${tvslaEscape(member.id)}"
>
                    ${tvslaEscape(member.name)}
</option>

            `
        ).join("");


const loans =
tvslaLoans();


const rows =
loans.length
        ? loans.map(
            loan => `

<tr>

<td>
                        ${tvslaEscape(loan.date)}
</td>

<td>
                        ${tvslaEscape(loan.memberName)}
</td>

<td style="text-align:right;">
                        ${tvslaMoney(loan.amount)}
</td>

<td style="text-align:right;">
                        ${tvslaMoney(loan.balance)}
</td>

<td>
                        ${tvslaEscape(loan.status)}
</td>

</tr>

            `
        ).join("")
        : `

<tr>
<td
colspan="5"
                    style="
text-align:center;
                        padding:15px;
                    "
>
                    No loans recorded.
</td>
</tr>

        `;


const modal =
tvslaModal(
            "TVSLA Loans",
            `

<form id="tvslaLoanForm">

<div style="
display:grid;
                    grid-template-columns:
                        repeat(
                            auto-fit,
minmax(190px,1fr)
                        );
                    gap:10px;
                ">

<input
                        id="tvslaLoanDate"
                        type="date"
                        value="${tvslaToday()}"
                        required
                        style="${tvslaInputStyle()}"
>


<select
                        id="tvslaLoanMember"
                        required
                        style="${tvslaInputStyle()}"
>

<option value="">
                            Select Member
</option>

                        ${memberOptions}

</select>


<input
                        id="tvslaLoanAmount"
                        type="number"
                        min="1"
                        placeholder="Loan Amount"
                        required
                        style="${tvslaInputStyle()}"
>


<input
                        id="tvslaLoanInterest"
                        type="number"
                        min="0"
                        step="0.01"
                        placeholder="Interest %"
                        value="0"
                        style="${tvslaInputStyle()}"
>


<input
                        id="tvslaLoanDueDate"
                        type="date"
                        style="${tvslaInputStyle()}"
>

</div>


<div style="
                    margin-top:12px;
                ">

                    ${tvslaButton(
                        "Issue Loan",
                        "tvslaIssueLoanBtn"
                    )}

                    ${tvslaButton(
                        "Back to Dashboard",
                        "tvslaLoanBackBtn",
                        true
                    )}

</div>

</form>


<div style="
                margin-top:18px;
overflow:auto;
            ">

<table style="
                    width:100%;
border-collapse:collapse;
                    font-size:12px;
                ">

<thead>

<tr style="
                            background:#eef7f1;
                        ">

<th>Date</th>
<th>Member</th>
<th>Loan</th>
<th>Balance</th>
<th>Status</th>

</tr>

</thead>

<tbody>
                        ${rows}
</tbody>

</table>

</div>

            `
        );


modal.querySelector(
        "#tvslaLoanForm"
    ).onsubmit =
        function(event) {

event.preventDefault();


const memberId =
modal.querySelector(
                    "#tvslaLoanMember"
                ).value;


const member =
tvslaMembers()
                    .find(
                        item =>
item.id ===
memberId
                    );


            if (!member) {

                alert(
                    "Select a member."
                );

                return;
            }


const principal =
                Number(
modal.querySelector(
                        "#tvslaLoanAmount"
                    ).value
                );


const interestRate =
                Number(
modal.querySelector(
                        "#tvslaLoanInterest"
                    ).value || 0
                );


const interest =
                principal *
interestRate /
                100;


const totalPayable =
                principal +
                interest;


const list =
tvslaLoans();


list.push({

                id:
tvslaID("LOAN"),

                date:
modal.querySelector(
                        "#tvslaLoanDate"
                    ).value,

memberId:
member.id,

memberName:
member.name,

                amount:
                    principal,

interestRate,

                interest,

totalPayable,

                balance:
totalPayable,

dueDate:
modal.querySelector(
                        "#tvslaLoanDueDate"
                    ).value,

                status:
                    "Outstanding",

approvedBy:
tvslaCurrentUserName(),

createdAt:
Date.now()

            });


tvslaWrite(
TVSLA_KEYS.loans,
                list
            );


            alert(
                "TVSLA loan recorded.\n\n" +
                "Factory accounts were not affected."
            );


openTVSLALoans();

        };


modal.querySelector(
        "#tvslaLoanBackBtn"
    ).onclick =
openTVSLADashboard;
}


/* =========================================================
   TRANSACTION HISTORY
   ========================================================= */

function openTVSLAHistory(filterType) {

    if (!tvslaDirector()) {

        alert(
            "Director access required."
        );

        return;
    }


    let transactions =
tvslaTransactions()
            .slice()
            .sort(
                (a, b) =>
                    Number(b.createdAt || 0) -
                    Number(a.createdAt || 0)
            );


    if (filterType) {

        transactions =
transactions.filter(
                transaction =>
transaction.type ===
filterType
            );
    }


const rows =
transactions.length
        ? transactions.map(
            transaction => `

<tr>

<td>
                        ${tvslaEscape(transaction.date)}
</td>

<td>
                        ${tvslaEscape(transaction.memberName)}
</td>

<td>
                        ${tvslaEscape(transaction.type)}
</td>

<td style="
text-align:right;
font-weight:bold;
                    ">
                        ${tvslaMoney(transaction.amount)}
</td>

<td>
                        ${tvslaEscape(
transaction.paymentMethod
                        )}
</td>

<td>
                        ${tvslaEscape(
transaction.reference
                        )}
</td>

<td>
                        ${tvslaEscape(
transaction.enteredBy
                        )}
</td>

</tr>

            `
        ).join("")
        : `

<tr>
<td
colspan="7"
                    style="
text-align:center;
                        padding:18px;
                    "
>
                    No transactions found.
</td>
</tr>

        `;


const modal =
tvslaModal(
filterType
                ? "TVSLA - " + filterType
                : "TVSLA Transaction History",
            `

<div style="overflow:auto;">

<table style="
                    width:100%;
border-collapse:collapse;
                    font-size:12px;
                ">

<thead>

<tr style="
                            background:#eef7f1;
                        ">

<th>Date</th>
<th>Member</th>
<th>Type</th>
<th>Amount</th>
<th>Method</th>
<th>Reference</th>
<th>Entered By</th>

</tr>

</thead>

<tbody>
                        ${rows}
</tbody>

</table>

</div>


<div style="
                margin-top:15px;
            ">

                ${tvslaButton(
                    "Back to Dashboard",
                    "tvslaHistoryBackBtn",
                    true
                )}

</div>

            `
        );


modal.querySelector(
        "#tvslaHistoryBackBtn"
    ).onclick =
openTVSLADashboard;
}


/* =========================================================
   MEMBER STATEMENT
   ========================================================= */

function openTVSLAMemberStatement() {

    if (!tvslaDirector()) {

        alert(
            "Director access required."
        );

        return;
    }


const members =
tvslaMembers();


const options =
members.map(
            member => `

<option
                    value="${tvslaEscape(member.id)}"
>
                    ${tvslaEscape(member.name)}
</option>

            `
        ).join("");


const modal =
tvslaModal(
            "TVSLA Member Statement",
            `

<label>
                Select Member

<select
                    id="tvslaStatementMember"
                    style="${tvslaInputStyle()}"
>

<option value="">
                        Select Member
</option>

                    ${options}

</select>

</label>


<div style="
                margin-top:12px;
            ">

                ${tvslaButton(
                    "View Statement",
                    "tvslaViewStatementBtn"
                )}

                ${tvslaButton(
                    "Back to Dashboard",
                    "tvslaStatementBackBtn",
                    true
                )}

</div>


<div
                id="tvslaStatementResults"
                style="
                    margin-top:18px;
                "
></div>

            `
        );


modal.querySelector(
        "#tvslaViewStatementBtn"
    ).onclick =
        function() {

const memberId =
modal.querySelector(
                    "#tvslaStatementMember"
                ).value;


const member =
tvslaMembers()
                    .find(
                        item =>
item.id ===
memberId
                    );


            if (!member) {

                alert(
                    "Select a member."
                );

                return;
            }


const transactions =
tvslaTransactions()
                    .filter(
                        transaction =>
transaction.memberId ===
memberId
                    );


const loans =
tvslaLoans()
                    .filter(
                        loan =>
loan.memberId ===
memberId
                    );


const savings =
                transactions
                    .filter(
                        transaction =>
transaction.type ===
                            "Savings"
                    )
                    .reduce(
                        (sum, transaction) =>
                            sum +
                            Number(
transaction.amount || 0
                            ),
                        0
                    );


const withdrawals =
                transactions
                    .filter(
                        transaction =>
transaction.type ===
                            "Withdrawal"
                    )
                    .reduce(
                        (sum, transaction) =>
                            sum +
                            Number(
transaction.amount || 0
                            ),
                        0
                    );


const outstanding =
loans.reduce(
                    (sum, loan) =>
                        sum +
                        Number(
loan.balance || 0
                        ),
                    0
                );


const rows =
transactions.length
                ? transactions.map(
                    transaction => `

<tr>

<td>
                                ${tvslaEscape(
transaction.date
                                )}
</td>

<td>
                                ${tvslaEscape(
transaction.type
                                )}
</td>

<td style="
text-align:right;
                            ">
                                ${tvslaMoney(
transaction.amount
                                )}
</td>

</tr>

                    `
                ).join("")
                : `

<tr>
<td colspan="3">
                            No transactions.
</td>
</tr>

                `;


modal.querySelector(
                "#tvslaStatementResults"
            ).innerHTML = `

<div style="
background:white;
                    border:1px solid #dce7df;
                    border-radius:10px;
                    padding:14px;
                ">

<h3 style="
                        color:#0b5d3b;
                        margin-top:0;
                    ">
                        ${tvslaEscape(member.name)}
</h3>

<div>
                        Savings:
<b>
                            UGX ${tvslaMoney(savings)}
</b>
</div>

<div>
                        Withdrawals:
<b>
                            UGX ${tvslaMoney(withdrawals)}
</b>
</div>

<div>
                        Net Savings:
<b>
                            UGX ${tvslaMoney(
                                savings -
                                withdrawals
                            )}
</b>
</div>

<div>
                        Outstanding Loans:
<b>
                            UGX ${tvslaMoney(
                                outstanding
                            )}
</b>
</div>

<table style="
                        width:100%;
                        margin-top:14px;
border-collapse:collapse;
                        font-size:12px;
                    ">

<thead>

<tr style="
                                background:#eef7f1;
                            ">

<th>Date</th>
<th>Transaction</th>
<th>Amount</th>

</tr>

</thead>

<tbody>
                            ${rows}
</tbody>

</table>

</div>

            `;

        };


modal.querySelector(
        "#tvslaStatementBackBtn"
    ).onclick =
openTVSLADashboard;
}


